CREATE TABLE social_profiles (owner_subject TEXT PRIMARY KEY, username TEXT UNIQUE, enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)), CHECK(username IS NULL OR username ~ '^[a-z][a-z0-9_]{2,29}$'));
CREATE TABLE social_friendships (id TEXT PRIMARY KEY, member_a TEXT NOT NULL REFERENCES social_profiles(owner_subject), member_b TEXT NOT NULL REFERENCES social_profiles(owner_subject), requester TEXT NOT NULL REFERENCES social_profiles(owner_subject), status TEXT NOT NULL CHECK(status IN('pending','accepted')), UNIQUE(member_a,member_b), CHECK(member_a<member_b), CHECK(requester=member_a OR requester=member_b));
CREATE TABLE social_shares (id TEXT PRIMARY KEY, friendship_id TEXT NOT NULL REFERENCES social_friendships(id) ON DELETE CASCADE, sender TEXT NOT NULL REFERENCES social_profiles(owner_subject), recipient TEXT NOT NULL REFERENCES social_profiles(owner_subject), url TEXT NOT NULL, title TEXT NOT NULL, note TEXT NOT NULL, recommend INTEGER NOT NULL CHECK(recommend IN(0,1)), dismissed INTEGER NOT NULL DEFAULT 0 CHECK(dismissed IN(0,1)), created_at TEXT NOT NULL, UNIQUE(sender,recipient,url), CHECK(sender<>recipient));
CREATE INDEX social_shares_recipient ON social_shares(recipient, dismissed);
